int hashtab_map(hashtab_t h,
                int (*apply) (hashtab_key_t k,
                              hashtab_datum_t d, void *args), void *args)
{
        unsigned int i;
        hashtab_ptr_t cur;
        int ret;

        if (!h)
                return SEPOL_OK;

        for (i = 0; i < h->size; i++) {
                cur = h->htable[i];
                while (cur != NULL) {
                        ret = apply(cur->key, cur->datum, args);
                        if (ret)
                                return ret;
                        cur = cur->next;
                }
        }
        return SEPOL_OK;
